-- ════════════════════════════════════════════════════════════════════
-- TRM001: MEASURED Terminal rules reconciled into prior-art ERP.db vocab
-- GENERATED by build/reconcile_terminal_rules.py — DO NOT HAND-EDIT.
-- Source: build/terminal_rules.db (mined+verified) + Terminal_meta.db (XYZ)
-- Implements RESUME_TERMINAL_RULE_MINING.md §PRIOR-ART RECONCILIATION.
-- Doctrine: flow measured rules INTO existing tables (provenance tagged),
-- don't fork a parallel schema. z_offset is FLOOR-relative (measured,
-- transfer-correct = what disc_walker.js uses); the placement_rule FK
-- carries the prior-art datum intent (e.g. CEILING_GRID). Two provenances.
-- ════════════════════════════════════════════════════════════════════

-- Adopts ad_placement_offset (DV042) vocabulary: z_rule/z_offset/x_ref/
-- y_ref/standard + a FK to the named rule. Measured grain (disc/class/
-- storey) -> a sibling of the named-rule dictionary, not a fork of it.
CREATE TABLE IF NOT EXISTS ad_placement_measured (
    ad_placement_measured_id INTEGER PRIMARY KEY AUTOINCREMENT,
    disc            TEXT NOT NULL,
    ifc_class       TEXT NOT NULL,
    ref_kind        TEXT,                 -- room | grid | host | storey | datum
    storey_scope    TEXT,
    from_edge_x     REAL DEFAULT 0,       -- measured dx (room/grid-relative)
    from_edge_y     REAL DEFAULT 0,       -- measured dy
    z_rule          TEXT DEFAULT 'FLOOR', -- adopted datum vocabulary
    z_offset        REAL DEFAULT 0,       -- measured dz, FLOOR-relative
    x_ref           TEXT DEFAULT 'CENTER',
    y_ref           TEXT DEFAULT 'CENTER',
    spacing_x_m     REAL DEFAULT 0,
    spacing_y_m     REAL DEFAULT 0,
    z_band_lo       REAL,
    z_band_hi       REAL,
    placement_rule  TEXT,                 -- FK -> ad_placement_offset.placement_rule
    standard        TEXT,                 -- copied from the FK'd named rule
    n_measured      INTEGER,
    src_storey_area_m2 REAL,             -- measured source-storey footprint (area-density bound)
    provenance      TEXT,
    src_guids       TEXT
);
CREATE TABLE IF NOT EXISTS ad_place_order (
    disc            TEXT NOT NULL,
    order_index     INTEGER NOT NULL,
    storey_scope    TEXT,
    z_band_lo       REAL,
    z_band_hi       REAL,
    n_measured      INTEGER,
    provenance      TEXT
);
-- Cross-discipline clearance / yield = the AD_Clash_Rule layer (SRS §6.3).
CREATE TABLE IF NOT EXISTS ad_clash_avoidance (
    disc_a          TEXT NOT NULL,
    disc_b          TEXT NOT NULL,
    min_clear_m     REAL,
    yields          TEXT,                 -- discipline that re-routes on conflict
    z_band          TEXT,
    n_measured      INTEGER,
    provenance      TEXT
);
-- Measured routing sibling (symmetric to ad_placement_measured): retains the
-- precise IFC classes the modeller's disc_walker Router matches against the
-- target building. ad_mep_pattern keeps the node-token rows for the prior-art
-- RouteWalker; this keeps IFC classes for the disc_walker. One mine, two views.
CREATE TABLE IF NOT EXISTS ad_routing_measured (
    disc            TEXT NOT NULL,
    from_ifc_class  TEXT NOT NULL,
    to_ifc_class    TEXT NOT NULL,
    pattern         TEXT,                 -- nn | main | riser | bend | array | grid
    params_json     TEXT,
    n_measured      INTEGER,
    provenance      TEXT,
    src_guids       TEXT
);
-- Terminal has IfcSpace=0 (LANDMINE) -> cannot key into ad_space_type_mep_bom
-- by space_type without inventing one. Kept as a measured per-scope count.
CREATE TABLE IF NOT EXISTS ad_space_bom_measured (
    disc            TEXT NOT NULL,
    scope           TEXT,
    ifc_class       TEXT,
    count_per       INTEGER,
    spacing_m       REAL,
    n_measured      INTEGER,
    provenance      TEXT,
    src_guids       TEXT
);

-- Re-run safe: purge prior measured:terminal rows before re-insert.
DELETE FROM ad_mep_anchor  WHERE anchor_id LIKE 'TRM:%';
DELETE FROM ad_mep_pattern WHERE source_building='Terminal' AND pattern_id LIKE 'TRM\_%' ESCAPE '\';
DELETE FROM ad_routing_measured;
DELETE FROM ad_placement_measured;
DELETE FROM ad_place_order;
DELETE FROM ad_clash_avoidance;
DELETE FROM ad_space_bom_measured;

-- ── rule_routing -> ad_mep_pattern (existing W019 table) ──

-- ── rule_placement -> ad_placement_measured (adopts DV042 vocabulary) ──

-- ── rule_space_bom -> ad_space_bom_measured (IfcSpace=0 gap, see header) ──

-- ── rule_place_order -> ad_place_order (NEW measured layer) ──

-- ── rule_avoidance -> ad_clash_avoidance (NEW measured layer) ──

-- ── disc_walker compatibility views (ERP.db as drop-in rule source) ──
DROP VIEW IF EXISTS rule_placement;
CREATE VIEW rule_placement AS
  SELECT disc, ifc_class, ref_kind, from_edge_x AS dx, from_edge_y AS dy,
         z_offset AS dz, spacing_x_m, spacing_y_m, z_band_lo, z_band_hi,
         storey_scope, n_measured, src_storey_area_m2, provenance, src_guids
  FROM ad_placement_measured;
DROP VIEW IF EXISTS rule_routing;
CREATE VIEW rule_routing AS
  SELECT disc, from_ifc_class AS from_kind, to_ifc_class AS to_kind, pattern,
         params_json, n_measured, provenance, src_guids
  FROM ad_routing_measured;
DROP VIEW IF EXISTS rule_place_order;
CREATE VIEW rule_place_order AS
  SELECT disc, order_index, storey_scope, z_band_lo, z_band_hi, n_measured, provenance
  FROM ad_place_order;
DROP VIEW IF EXISTS rule_avoidance;
CREATE VIEW rule_avoidance AS
  SELECT disc_a, disc_b, min_clear_m, yields, z_band, n_measured, provenance
  FROM ad_clash_avoidance;
DROP VIEW IF EXISTS rule_space_bom;
CREATE VIEW rule_space_bom AS
  SELECT disc, scope, ifc_class, count_per, spacing_m, n_measured, provenance, src_guids
  FROM ad_space_bom_measured;

